import { useState } from "react";
import { useNavigate } from "@/lib/router-compat";
import { motion } from "framer-motion";
import { Receipt, ShoppingBag, Clock, CircleCheck as CheckCircle2, Circle as XCircle, ChefHat, Package, Truck } from "lucide-react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { Skeleton } from "@/components/ui/skeleton";
import { useOrders } from "@/contexts/orders-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { formatRand, formatDate } from "@/services/payplate-data";
import { cn } from "@/lib/utils";
import type { OrderStatus } from "@/types/payplate";

type Tab = "active" | "completed" | "cancelled";

const statusConfig: Record<OrderStatus, { label: string; color: string }> = {
  pending: { label: "Pending", color: "text-warning bg-warning/10" },
  preparing: { label: "Preparing", color: "text-primary bg-primary/10" },
  ready: { label: "Ready", color: "text-success bg-success/10" },
  delivered: { label: "Delivered", color: "text-muted-foreground bg-muted" },
  cancelled: { label: "Cancelled", color: "text-danger bg-danger/10" },
};

const timelineSteps: { status: OrderStatus; label: string; icon: React.ReactNode }[] = [
  { status: "pending", label: "Order placed", icon: <Receipt size={14} /> },
  { status: "preparing", label: "Preparing", icon: <ChefHat size={14} /> },
  { status: "ready", label: "Ready for pickup", icon: <Package size={14} /> },
  { status: "delivered", label: "Delivered", icon: <CheckCircle2 size={14} /> },
];

function getTimelineProgress(status: OrderStatus): number {
  const idx = timelineSteps.findIndex((s) => s.status === status);
  if (status === "cancelled") return -1;
  return idx;
}

export function OrdersPage() {
  const { orders, isLoading } = useOrders();
  const navigate = useNavigate();
  const reduced = usePrefersReducedMotion();
  const [activeTab, setActiveTab] = useState<Tab>("active");

  const activeOrders = orders.filter((o) => o.status === "pending" || o.status === "preparing" || o.status === "ready");
  const completedOrders = orders.filter((o) => o.status === "delivered");
  const cancelledOrders = orders.filter((o) => o.status === "cancelled");

  const tabOrders = activeTab === "active" ? activeOrders : activeTab === "completed" ? completedOrders : cancelledOrders;

  const tabs: { key: Tab; label: string; count: number }[] = [
    { key: "active", label: "Active", count: activeOrders.length },
    { key: "completed", label: "Completed", count: completedOrders.length },
    { key: "cancelled", label: "Cancelled", count: cancelledOrders.length },
  ];

  if (!isLoading && orders.length === 0) {
    return (
      <AppShell>
        <EmptyState
          icon={<ShoppingBag size={32} />}
          title="No orders yet"
          description="Your order history will appear here once you place your first order."
          action={<Button onClick={() => navigate("/restaurants")}>Browse restaurants</Button>}
        />
      </AppShell>
    );
  }

  return (
    <AppShell>
      <div className="space-y-6">
        <div>
          <h1 className="font-heading text-2xl font-black lg:text-3xl">Your orders</h1>
          <p className="mt-1 text-sm text-muted-foreground">Track and manage your food orders</p>
        </div>

        {/* Tabs */}
        <div className="flex gap-2">
          {tabs.map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={cn(
                "inline-flex items-center gap-2 rounded-full px-4 py-2 text-sm font-bold transition-all",
                activeTab === tab.key
                  ? "bg-primary text-white shadow-lift"
                  : "bg-card text-muted-foreground ring-1 ring-border hover:text-text",
              )}
            >
              {tab.label}
              {tab.count > 0 && (
                <span className={cn(
                  "grid min-w-5 place-items-center rounded-full px-1 text-xs",
                  activeTab === tab.key ? "bg-white/20" : "bg-muted",
                )}>
                  {tab.count}
                </span>
              )}
            </button>
          ))}
        </div>

        {/* Orders list */}
        {isLoading ? (
          <div className="space-y-4">
            {[1, 2, 3].map((i) => <Skeleton key={i} className="h-40" />)}
          </div>
        ) : tabOrders.length === 0 ? (
          <Card className="py-12 text-center">
            <ShoppingBag size={32} className="mx-auto text-muted-foreground" />
            <p className="mt-3 text-sm text-muted-foreground">No {activeTab} orders</p>
          </Card>
        ) : (
          <div className="space-y-4">
            {tabOrders.map((order, i) => {
              const status = statusConfig[order.status];
              const timelineProgress = getTimelineProgress(order.status);
              return (
                <motion.div
                  key={order.id}
                  initial={reduced ? undefined : { opacity: 0, y: 15 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.05 }}
                >
                  <Card>
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <h3 className="font-heading font-black">{order.restaurantName}</h3>
                          <span className={cn("rounded-full px-2.5 py-1 text-xs font-bold", status.color)}>
                            {status.label}
                          </span>
                        </div>
                        <p className="mt-1 text-sm text-muted-foreground">
                          {formatDate(order.createdAt)} · {order.items.length} item{order.items.length > 1 ? "s" : ""}
                        </p>
                        <p className="mt-1 inline-flex items-center gap-1 text-xs text-muted-foreground">
                          <Clock size={12} /> Ready by {formatDate(order.estimatedReadyAt)}
                        </p>
                      </div>
                      <div className="text-right">
                        <p className="font-heading text-lg font-black tabular-nums">{formatRand(order.totalCents)}</p>
                        <p className="text-xs capitalize text-muted-foreground">{order.orderType} · {order.paymentMethod}</p>
                      </div>
                    </div>

                    {/* Timeline for active orders */}
                    {activeTab === "active" && order.status !== "cancelled" && timelineProgress >= 0 && (
                      <div className="mt-4 border-t border-border pt-4">
                        <div className="flex items-center justify-between">
                          {timelineSteps.map((step, idx) => {
                            const isComplete = idx <= timelineProgress;
                            const isCurrent = idx === timelineProgress;
                            return (
                              <div key={step.status} className="flex flex-1 flex-col items-center gap-1.5">
                                <div className={cn(
                                  "grid size-8 place-items-center rounded-full transition-all",
                                  isComplete ? "bg-primary text-white" : "bg-muted text-muted-foreground",
                                  isCurrent && "ring-2 ring-primary/30 ring-offset-2 ring-offset-card",
                                )}>
                                  {step.icon}
                                </div>
                                <span className={cn(
                                  "text-[10px] font-bold text-center",
                                  isComplete ? "text-text" : "text-muted-foreground",
                                )}>
                                  {step.label}
                                </span>
                                {idx < timelineSteps.length - 1 && (
                                  <div className={cn(
                                    "absolute h-0.5",
                                    idx < timelineProgress ? "bg-primary" : "bg-border",
                                  )} style={{ left: `${(idx + 1) * 25}%`, width: "25%" }} />
                                )}
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}

                    {/* Items */}
                    <div className="mt-3 border-t border-border pt-3">
                      <div className="flex flex-wrap gap-2 text-xs text-muted-foreground">
                        {order.items.map((ci) => (
                          <span key={ci.item.id} className="rounded-lg bg-muted px-2 py-1">
                            {ci.quantity}× {ci.item.name}
                          </span>
                        ))}
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="mt-4 flex gap-2">
                      <Button variant="secondary" className="text-sm" onClick={() => navigate(`/payment-success/${order.id}`)}>
                        <Receipt size={16} /> View receipt
                      </Button>
                      {order.status === "cancelled" && (
                        <span className="inline-flex items-center gap-1 text-xs font-bold text-danger">
                          <XCircle size={14} /> Order cancelled
                        </span>
                      )}
                    </div>
                  </Card>
                </motion.div>
              );
            })}
          </div>
        )}
      </div>
    </AppShell>
  );
}

import { useState } from "react";
import { motion } from "framer-motion";
import { Plus, TrendingDown, Trophy, QrCode, ArrowUpRight, ArrowDownLeft, Wallet, Receipt, Sparkles } from "lucide-react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Dialog } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { TransactionRow } from "@/components/domain/transaction-row";
import { useWallet } from "@/contexts/wallet-context";
import { useToast } from "@/contexts/toast-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { formatRand } from "@/services/payplate-data";
import { cn } from "@/lib/utils";

type Tab = "all" | "topup" | "payment" | "reward";

export function WalletPage() {
  const { balanceCents, transactions, totalSpentThisMonthCents, rewardPoints, tier, tierProgressPercent, topUp, isLoading } = useWallet();
  const { showToast } = useToast();
  const reduced = usePrefersReducedMotion();
  const [showTopUp, setShowTopUp] = useState(false);
  const [topUpAmount, setTopUpAmount] = useState("");
  const [showQR, setShowQR] = useState(false);
  const [activeTab, setActiveTab] = useState<Tab>("all");

  function handleTopUp() {
    const amount = parseFloat(topUpAmount);
    if (isNaN(amount) || amount <= 0) {
      showToast("Enter a valid amount", "error");
      return;
    }
    topUp(Math.round(amount * 100));
    showToast(`Topped up ${formatRand(Math.round(amount * 100))}`, "success");
    setTopUpAmount("");
    setShowTopUp(false);
  }

  const filteredTransactions = activeTab === "all"
    ? transactions
    : transactions.filter((t) => t.type === activeTab);

  const tabs: { key: Tab; label: string }[] = [
    { key: "all", label: "All" },
    { key: "topup", label: "Top-ups" },
    { key: "payment", label: "Payments" },
    { key: "reward", label: "Rewards" },
  ];

  const quickActions = [
    { icon: <Plus size={22} />, label: "Top up", onClick: () => setShowTopUp(true), color: "bg-primary/10 text-primary" },
    { icon: <QrCode size={22} />, label: "Scan QR", onClick: () => setShowQR(true), color: "bg-accent/10 text-accent" },
    { icon: <ArrowUpRight size={22} />, label: "Send", onClick: () => showToast("Coming soon", "info"), color: "bg-rewards/10 text-rewards" },
    { icon: <ArrowDownLeft size={22} />, label: "Request", onClick: () => showToast("Coming soon", "info"), color: "bg-blue-500/10 text-blue-500" },
  ];

  return (
    <AppShell>
      <div className="space-y-6">
        <div>
          <h1 className="font-heading text-2xl font-black lg:text-3xl">Wallet</h1>
          <p className="mt-1 text-sm text-muted-foreground">Balance, payments & rewards</p>
        </div>

        {/* Stacked wallet cards */}
        <div className="relative">
          {/* Back card (reward tier) */}
          <div className="absolute -bottom-3 left-3 right-3 h-24 rounded-3xl bg-gradient-to-r from-rewards/80 to-amber-600/80 opacity-60 blur-[1px]" />

          {/* Main wallet card */}
          <motion.div
            initial={reduced ? undefined : { opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-primary via-primary-600 to-dark p-6 text-white shadow-lift"
          >
            {/* Ambient blobs */}
            <div className="pointer-events-none absolute -right-12 -top-12 size-48 rounded-full bg-white/10 blur-2xl" />
            <div className="pointer-events-none absolute -bottom-16 -left-8 size-40 rounded-full bg-accent/20 blur-2xl" />

            <div className="relative flex items-start justify-between">
              <div>
                <p className="text-xs font-bold uppercase tracking-wide text-white/70">PayPlate Wallet</p>
                <div className="mt-3 flex items-center gap-2">
                  <Wallet size={16} className="text-white/80" />
                  <span className="text-xs font-bold capitalize text-white/70">{tier} tier</span>
                </div>
              </div>
              <div className="grid size-10 place-items-center rounded-xl bg-white/15 backdrop-blur-sm">
                <Wallet size={18} />
              </div>
            </div>

            <div className="relative mt-6">
              <motion.p
                key={balanceCents}
                initial={reduced ? undefined : { opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                className="font-heading text-4xl font-black tabular-nums"
              >
                {formatRand(balanceCents)}
              </motion.p>
              <p className="mt-1 text-sm text-white/70">{rewardPoints} reward points</p>
            </div>

            <div className="relative mt-5 flex items-center justify-between">
              <div className="space-y-1">
                <div className="h-1 w-12 rounded-full bg-white/30" />
                <div className="h-1 w-8 rounded-full bg-white/20" />
              </div>
              <div className="rounded-lg bg-white/15 px-3 py-1.5 text-xs font-black backdrop-blur-sm">
                •••• 2026
              </div>
            </div>
          </motion.div>
        </div>

        {/* Quick actions grid */}
        <div className="grid grid-cols-4 gap-3">
          {quickActions.map((action) => (
            <button
              key={action.label}
              onClick={action.onClick}
              className="flex flex-col items-center gap-1.5"
            >
              <div className={cn("grid size-14 place-items-center rounded-2xl transition-transform active:scale-90", action.color)}>
                {action.icon}
              </div>
              <span className="text-xs font-bold">{action.label}</span>
            </button>
          ))}
        </div>

        {/* Analytics cards */}
        <div className="grid grid-cols-2 gap-4">
          <Card className="p-4">
            <div className="flex items-center gap-2">
              <div className="grid size-10 place-items-center rounded-xl bg-danger/10 text-danger">
                <TrendingDown size={18} />
              </div>
              <div>
                <p className="text-xs text-muted-foreground">Spent this month</p>
                <p className="font-heading text-lg font-black tabular-nums">{formatRand(totalSpentThisMonthCents)}</p>
              </div>
            </div>
          </Card>
          <Card className="p-4">
            <div className="flex items-center gap-2">
              <div className="grid size-10 place-items-center rounded-xl bg-rewards/10 text-rewards">
                <Trophy size={18} />
              </div>
              <div>
                <p className="text-xs text-muted-foreground">Reward tier</p>
                <p className="font-heading text-lg font-black capitalize">{tier} · {rewardPoints} pts</p>
              </div>
            </div>
          </Card>
        </div>

        {/* Tier progress bar */}
        <Card>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Sparkles size={16} className="text-primary" />
              <h3 className="font-heading font-black">Tier progress</h3>
            </div>
            <span className="text-sm font-bold text-primary">{Math.round(tierProgressPercent)}%</span>
          </div>
          <div className="mt-3 h-3 overflow-hidden rounded-full bg-muted">
            <motion.div
              initial={reduced ? undefined : { width: 0 }}
              animate={{ width: `${tierProgressPercent}%` }}
              transition={{ duration: 0.8, ease: "easeOut" }}
              className="h-full rounded-full bg-gradient-to-r from-primary to-accent"
            />
          </div>
          <p className="mt-2 text-xs text-muted-foreground">
            {tier === "diamond" ? "Max tier reached!" : `Earn ${2000 - rewardPoints} more points to reach ${tier === "bronze" ? "Silver" : tier === "silver" ? "Gold" : "Diamond"}`}
          </p>
        </Card>

        {/* Transactions */}
        <div>
          <div className="mb-3 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Receipt size={18} className="text-primary" />
              <h3 className="font-heading text-lg font-black">Recent activity</h3>
            </div>
          </div>

          {/* Tab filter pills */}
          <div className="mb-3 flex gap-2">
            {tabs.map((tab) => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={cn(
                  "rounded-full px-3 py-1.5 text-xs font-bold transition-all",
                  activeTab === tab.key
                    ? "bg-primary text-white"
                    : "bg-card text-muted-foreground ring-1 ring-border",
                )}
              >
                {tab.label}
              </button>
            ))}
          </div>

          {isLoading ? (
            <div className="space-y-3">
              {[1, 2, 3, 4].map((i) => <Skeleton key={i} className="h-16" />)}
            </div>
          ) : filteredTransactions.length === 0 ? (
            <Card className="py-8 text-center">
              <Wallet size={32} className="mx-auto text-muted-foreground" />
              <p className="mt-3 text-sm text-muted-foreground">No transactions yet</p>
            </Card>
          ) : (
            <Card className="divide-y divide-border p-0">
              {filteredTransactions.map((t) => (
                <div key={t.id} className="p-4">
                  <TransactionRow transaction={t} />
                </div>
              ))}
            </Card>
          )}
        </div>
      </div>

      {/* Top-up dialog */}
      <Dialog open={showTopUp} onClose={() => setShowTopUp(false)} title="Top up wallet">
        <div className="space-y-4">
          <div className="rounded-2xl bg-primary/5 p-4 text-center">
            <p className="text-xs text-muted-foreground">Current balance</p>
            <p className="font-heading text-2xl font-black text-primary">{formatRand(balanceCents)}</p>
          </div>
          <Input
            label="Amount (R)"
            type="number"
            placeholder="e.g. 100"
            value={topUpAmount}
            onChange={(e) => setTopUpAmount(e.target.value)}
            autoFocus
          />
          <div className="flex gap-2">
            {[50, 100, 200].map((amt) => (
              <button
                key={amt}
                onClick={() => setTopUpAmount(String(amt))}
                className="flex-1 rounded-xl bg-muted py-2 text-sm font-bold transition-colors hover:bg-primary/10 hover:text-primary"
              >
                R{amt}
              </button>
            ))}
          </div>
          <Button className="w-full" onClick={handleTopUp}>Top up</Button>
        </div>
      </Dialog>

      {/* QR dialog */}
      <Dialog open={showQR} onClose={() => setShowQR(false)} title="Pay via QR">
        <div className="flex flex-col items-center py-4">
          <div className="grid size-48 place-items-center rounded-3xl border-2 border-border bg-card">
            <QrCode size={120} className="text-primary" />
          </div>
          <p className="mt-4 text-sm text-muted-foreground">Show this code to the cashier to pay</p>
          <p className="mt-1 font-heading text-lg font-black">{formatRand(balanceCents)} available</p>
        </div>
      </Dialog>
    </AppShell>
  );
}

import { useEffect, useState } from "react";
import { Link, useNavigate } from "@/lib/router-compat";
import { motion } from "framer-motion";
import {
  Search, Bell, MapPin, Flame, ArrowRight, Star,
  ChevronRight, RotateCcw, Tag, Clock,
  Grid2x2, Sandwich, Pizza, CupSoda, Salad, Coffee, Fish,
} from "lucide-react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { RestaurantCard } from "@/components/domain/restaurant-card";
import { MenuItemCard } from "@/components/domain/menu-item-card";
import { useAuth } from "@/contexts/auth-context";
import { useWallet } from "@/contexts/wallet-context";
import { useRestaurants } from "@/contexts/restaurants-context";
import { useOrders } from "@/contexts/orders-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { allMenuItems, offers, recentlyOrderedItemIds, formatRand } from "@/services/payplate-data";
import type { Restaurant, MenuItem, Offer } from "@/types/payplate";

const CATEGORIES = [
  { icon: Grid2x2,  label: "All",     active: true  },
  { icon: Sandwich, label: "Burgers" },
  { icon: Pizza,    label: "Pizza"   },
  { icon: CupSoda,  label: "Drinks"  },
  { icon: Salad,    label: "Salads"  },
  { icon: Coffee,   label: "Coffee"  },
  { icon: Fish,     label: "Sushi"   },
];

export function Dashboard() {
  const { user } = useAuth();
  const { balanceCents, rewardPoints, tier } = useWallet();
  const { restaurants, isLoading } = useRestaurants();
  const { orders } = useOrders();
  const reduced = usePrefersReducedMotion();
  const navigate = useNavigate();

  const [searchQuery, setSearchQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState("All");
  const [popularMeals]  = useState<MenuItem[]>(allMenuItems.filter((m) => m.isPopular));
  const [recentlyOrdered] = useState<MenuItem[]>(
    recentlyOrderedItemIds
      .map((id) => allMenuItems.find((m) => m.id === id))
      .filter(Boolean) as MenuItem[],
  );
  const [nearby, setNearby] = useState<Restaurant[]>([]);
  const [studentOffers] = useState<Offer[]>(offers.filter((o) => o.isStudentExclusive));

  useEffect(() => {
    setNearby([...restaurants].sort((a, b) => parseFloat(a.distance) - parseFloat(b.distance)));
  }, [restaurants]);

  const firstName = user ? user.fullName.split(" ")[0] : "there";
  const hour = new Date().getHours();
  const greeting = hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening";
  const lastOrder = orders[0];

  function handleSearch(e: React.FormEvent) {
    e.preventDefault();
    if (searchQuery.trim()) navigate(`/restaurants?q=${encodeURIComponent(searchQuery)}`);
  }

  return (
    <AppShell>
      <div className="space-y-5">
        {/* Header row */}
        <motion.div
          initial={reduced ? undefined : { opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-start justify-between gap-3"
        >
          <div>
            <button
              onClick={() => navigate("/restaurants")}
              className="inline-flex items-center gap-1 text-sm font-bold text-muted-foreground hover:text-primary transition-colors"
            >
              <MapPin size={14} className="text-primary" />
              University of Cape Town
              <ChevronRight size={14} />
            </button>
            <h1 className="mt-0.5 font-heading text-xl font-black">
              {greeting}, {firstName} 👋
            </h1>
          </div>
          <Link
            to="/notifications"
            className="relative grid size-10 shrink-0 place-items-center rounded-2xl bg-card ring-1 ring-border shadow-card"
          >
            <Bell size={18} />
            <span className="absolute right-2 top-2 size-2 rounded-full bg-primary" />
          </Link>
        </motion.div>

        {/* Search bar */}
        <motion.form
          onSubmit={handleSearch}
          initial={reduced ? undefined : { opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.05 }}
        >
          <label className="flex items-center gap-2.5 rounded-2xl bg-card px-4 py-3 ring-1 ring-border shadow-card transition-shadow focus-within:ring-primary/40 focus-within:shadow-lift">
            <Search size={17} className="shrink-0 text-muted-foreground" />
            <input
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search food, restaurants..."
              className="flex-1 bg-transparent text-sm font-medium text-text placeholder:text-muted-foreground outline-none"
            />
          </label>
        </motion.form>

        {/* Category chips */}
        <div className="scroll-snap-x">
          {CATEGORIES.map((cat) => (
            <button
              key={cat.label}
